def health():
    return jsonify({\"status\":\"ok\",\"server\":\"najika-world-v5\"})

@app.route(\"/api/world/info\")
def world_info():
    return jsonify({
        \"seed\": najika_world.seed,
        \"world_size\": najika_world.world_size,
        \"player_pos\": najika_world.player_pos,
        \"buildings\": len(najika_world.buildings),
        \"current_tile\": najika_world.get_current_tile()
    })

@app.route(\"/api/world/visible\")
def world_visible():
    radius = request.args.get(\"radius\", 5, type=int)
    visible = najika_world.get_visible_area(radius)
    current = najika_world.get_current_tile()
    return jsonify({
        \"visible\": visible,
        \"radius\": radius,
        \"player_pos\": najika_world.player_pos,
        \"current_tile\": current
    })

@app.route(\"/api/world/move\", methods=[\"POST\"])
def world_move():
    direction = request.json.get(\"direction\", \"\")
    if direction not in [\"north\", \"south\", \"east\", \"west\"]:
        return jsonify({\"error\": \"Invalid direction\"}), 400

    tile = najika_world.move_player(direction)
    visible = najika_world.get_visible_area(5)

    return jsonify({
        \"success\": True,
        \"tile\": tile,
        \"player_pos\": najika_world.player_pos,
        \"visible\": visible
    })

@app.route(\"/api/building/enter/<building_id>\")
def building_enter(building_id):
    result = najika_world.enter_building(building_id)
    return jsonify(result)

@app.route(\"/api/buildings/list\")
def buildings_list():
    return jsonify({\"buildings\": najika_world.buildings})

@app.route(\"/api/world/save\", methods=[\"POST\"])
def world_save():
    try:
        najika_world.save_world()
        return jsonify({\"success\": True, \"message\": \"Gespeichert!\"})
    except Exception as e:
        return jsonify({\"success\": False, \"message\": str(e)}), 500

@app.route(\"/api/world/load\", methods=[\"POST\"])
def world_load():
    try:
        success = najika_world.load_world()
        if success:
            return jsonify({
                \"success\": True,
                \"message\": \"Geladen!\",
                \"world_info\": {
                    \"seed\": najika_world.seed,
                    \"player_pos\": najika_world.player_pos
                }
            })
        return jsonify({\"success\": False, \"message\": \"Keine Welt!\"})
    except Exception as e:
        return jsonify({\"success\": False, \"message\": str(e)}), 500

@socketio.on(\"connect\")
def handle_connect():
    print(\"[CONNECT] Client\")
    emit(\"response\", {\"message\": \"Najika World bereit!\", \"type\": \"system\"})

@socketio.on(\"message\")
def handle_message(data):
    msg = data.get(\"message\", \"\").strip()
    if not msg:
        return
    print(f\"[USER] {msg}\")
    emit(\"response\", {\"message\": f\"Najika: {msg}\", \"type\": \"chat\"})

if __name__ == \"__main__\":
