# -*- coding: utf-8 -*-
import json, random, os

class NajikaWorld:
    def __init__(self):
        self.world_size = (100, 100)
        self.seed = random.randint(0, 999999)
        self.player_pos = [50, 50]
        self.buildings = {
            "schwarze_muehle": {
                "position": [50, 50],
                "name": "Schwarze Muehle",
                "floors": {
                    "erdgeschoss": ["wohnzimmer", "kueche", "bad"],
                    "obergeschoss": ["schlafzimmer", "musikzimmer"],
                    "keller": ["training", "studieren"]
                }
            }
        }
        self.world_tiles = []
        self.generate_world()

    def generate_world(self):
        print(f"[WORLD] Seed: {self.seed}")
        for y in range(100):
            row = []
            for x in range(100):
                if x == 50 and y == 50:
                    row.append("schwarze_muehle")
                else:
                    biomes = ["forest", "meadow", "lake", "mountain"]
                    row.append(random.choice(biomes))
            self.world_tiles.append(row)
        print("[OK] World generiert")

    def move_player(self, direction):
        x, y = self.player_pos
        if direction=="north" and y>0: y-=1
        elif direction=="south" and y<99: y+=1
        elif direction=="west" and x>0: x-=1
        elif direction=="east" and x<99: x+=1
        self.player_pos = [x, y]
        return self.get_current_tile()

    def get_current_tile(self):
        x, y = self.player_pos
        biome = self.world_tiles[y][x]
        building = None
        if biome == "schwarze_muehle":
            building = self.buildings["schwarze_muehle"]

# -*- coding: utf-8 -*-
from flask import Flask, request, jsonify
from flask_cors import CORS
import json
from world_system import NajikaWorld

app = Flask(__name__)
CORS(app)

print("="*70)
print("NAJIKA WORLD SERVER")
print("="*70)

najika_world = NajikaWorld()
print(f"[OK] Seed: {najika_world.seed}")
print()

@app.route("/")
def index():
    return jsonify({"status": "ok", "message": "Najika World Server"})

@app.route("/api/world/info")
def world_info():
    return jsonify({
        "seed": najika_world.seed,
        "player_pos": najika_world.player_pos,
        "current_tile": najika_world.get_current_tile()
    })

@app.route("/api/world/move", methods=["POST"])
def world_move():
    direction = request.json.get("direction", "")
    if direction not in ["north", "south", "east", "west"]:
        return jsonify({"error": "Invalid"}), 400
    tile = najika_world.move_player(direction)
    return jsonify({"success": True, "tile": tile, "player_pos": najika_world.player_pos})

@app.route("/api/world/visible")
def world_visible():
    visible = najika_world.get_visible_area(5)
    return jsonify({"visible": visible, "player_pos": najika_world.player_pos})

if __name__ == "__main__":
    print("[INFO] Server Port 7010")
    print("="*70)
    app.run(host="127.0.0.1", port=7010, debug=False)

