        padding: '15px',
        borderRadius: '10px',
        fontFamily: 'monospace',
        fontSize: '14px',
        zIndex: 100
      }}>
        <div style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '10px' }}>
          🏠 {roomData.name}
        </div>
        <div>WASD - Move</div>
        <div>E - Exit (near door)</div>
      </div>

      {/* Exit button */}
      <div style={{
        position: 'absolute',
        bottom: '30px',
        right: '30px',
        zIndex: 100
      }}>
