                  onClick={() => handleRoomChange(room.name)}
                  style={{
                    display: 'block',
                    width: '100%',
                    marginBottom: '5px',
                    padding: '8px',
                    background: currentRoom === room.name ? '#FF6B9D' : '#444',
                    border: 'none',
                    color: 'white',
                    borderRadius: '5px',
                    cursor: 'pointer',
                    fontSize: '11px'
                  }}
                >
                  {room.name}
                </button>
              ))
            }
          </div>
        )}

        <InteriorScene roomName={currentRoom} onExit={handleExitToWorld} />
      </div>
